import { fetchWithAuth } from "@/lib/api";
import type {
  MenuOrder,
  MenuOrderRefund,
  MenuOrderCreatePayload,
  MenuOrderCreated,
  MenuOrderSettings,
  MenuOrderSettingsUpdate,
  MenuOrderShippingQuoteRequest,
  MenuOrderShippingQuoteResponse,
  MenuOrderStatus,
  MenuOrderStatusUpdate,
} from "@/types/menuOrder";

const privateBase = "/api/menu-orders";
const publicBase = "/api/public/menu-orders";
const guestUrl = (orderNumber: string, token: string, suffix: string) =>
  `${publicBase}/${encodeURIComponent(orderNumber)}${suffix}?${new URLSearchParams({ management_token: token })}`;

async function readRefunds(response: Response): Promise<MenuOrderRefund[]> {
  const data: unknown = await response.json();
  if (Array.isArray(data)) return data as MenuOrderRefund[];
  if (data && typeof data === "object") {
    const record = data as Record<string, unknown>;
    const items = record.items ?? record.refunds ?? record.results ?? record.data;
    if (Array.isArray(items)) return items as MenuOrderRefund[];
  }
  return [];
}

function extractError(value: unknown): string | undefined {
  if (typeof value === "string") return value;

  if (Array.isArray(value)) {
    const parts = value.map(extractError).filter(Boolean);
    return parts.length ? parts.join("; ") : undefined;
  }

  if (value && typeof value === "object") {
    const record = value as Record<string, unknown>;
    return extractError(
      record.detail ?? record.message ?? record.msg ?? record.error,
    );
  }

  return undefined;
}

async function throwForResponse(response: Response): Promise<never> {
  const body: unknown = await response.json().catch(() => null);
  const detail = extractError(body);

  if (response.status === 400) {
    throw new Error(detail || "Revisa los datos capturados.");
  }
  if (response.status === 401) {
    throw new Error(detail || "Debes iniciar sesión para realizar esta acción.");
  }
  if (response.status === 403) {
    throw new Error(detail || "No tienes permiso para realizar esta acción.");
  }
  if (response.status === 404) {
    throw new Error(detail || "El pedido o menú solicitado no existe.");
  }
  if (response.status === 409) {
    throw new Error(
      detail || "La operación ya no se puede completar en el estado actual.",
    );
  }
  if (response.status === 422) {
    throw new Error(
      detail || "Revisa los datos del pedido e inténtalo nuevamente.",
    );
  }
  if (response.status === 429) {
    throw new Error(
      "Se hicieron demasiados intentos. Espera un momento e inténtalo de nuevo.",
    );
  }
  if ([502, 503, 504].includes(response.status)) {
    throw new Error(
      detail || "No se pudo comunicar con el servicio de pedidos.",
    );
  }

  throw new Error(
    detail || `No se pudo completar la solicitud (${response.status}).`,
  );
}

async function publicRequest(
  url: string,
  options?: RequestInit,
): Promise<Response> {
  const response = await fetch(url, {
    cache: "no-store",
    ...options,
  });

  if (!response.ok) await throwForResponse(response);
  return response;
}

async function authRequest(
  url: string,
  options?: Parameters<typeof fetchWithAuth>[1],
): Promise<Response> {
  const response = await fetchWithAuth(url, {
    cache: "no-store",
    ...options,
  });

  if (!response.ok) await throwForResponse(response);
  return response;
}

function buildStatusQuery(status?: MenuOrderStatus | null) {
  if (!status) return "";
  const params = new URLSearchParams({ status });
  return `?${params.toString()}`;
}

function defaultPublicSettings(menuId: number): MenuOrderSettings {
  return {
    menu_id: menuId,
    supplier_id: 0,
    orders_enabled_by_plan: false,
    accepts_orders: false,
    allows_pickup: true,
    allows_delivery: false,
    allow_guest_orders: true,
    allows_cash: true,
    allows_online_payment: false,
    mercadopago_linked: false,
    online_payment_available: false,
  };
}

function normalizeSettings(
  data: unknown,
  menuId: number,
): MenuOrderSettings {
  if (!data || typeof data !== "object") {
    return defaultPublicSettings(menuId);
  }

  const settings = data as Partial<MenuOrderSettings>;

  return {
    menu_id: typeof settings.menu_id === "number" ? settings.menu_id : menuId,
    supplier_id:
      typeof settings.supplier_id === "number" ? settings.supplier_id : 0,
    orders_enabled_by_plan: settings.orders_enabled_by_plan === true,
    accepts_orders: settings.orders_enabled_by_plan === true && settings.accepts_orders === true,
    allows_pickup: settings.allows_pickup !== false,
    allows_delivery: settings.allows_delivery === true,
    allow_guest_orders: settings.allow_guest_orders !== false,
    allows_cash: settings.allows_cash !== false,
    allows_online_payment: settings.orders_enabled_by_plan === true && settings.allows_online_payment === true,
    mercadopago_linked: settings.mercadopago_linked === true,
    online_payment_available: settings.orders_enabled_by_plan === true && settings.online_payment_available === true,
  };
}

export const menuOrderService = {
  async cancelCustomerOrder(orderId: number, reason: string): Promise<MenuOrder> {
    return (await authRequest(`${privateBase}/${orderId}/cancel`, { method: "POST", body: JSON.stringify({ reason }) })).json();
  },
  async cancelGuestOrder(orderNumber: string, managementToken: string, reason: string): Promise<MenuOrder> {
    return (await publicRequest(guestUrl(orderNumber, managementToken, "/cancel"), { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ reason }) })).json();
  },
  async providerCancelOrder(orderId: number, reason: string): Promise<MenuOrder> {
    return (await authRequest(`${privateBase}/${orderId}/provider-cancel`, { method: "POST", body: JSON.stringify({ reason }) })).json();
  },
  async markNoShow(orderId: number): Promise<MenuOrder> {
    return (await authRequest(`${privateBase}/${orderId}/no-show`, { method: "POST" })).json();
  },
  async requestCustomerRefund(orderId: number, reason: string): Promise<MenuOrderRefund> {
    return (await authRequest(`${privateBase}/${orderId}/refunds`, { method: "POST", body: JSON.stringify({ reason }) })).json();
  },
  async requestGuestRefund(orderNumber: string, managementToken: string, reason: string): Promise<MenuOrderRefund> {
    return (await publicRequest(guestUrl(orderNumber, managementToken, "/refunds"), { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ reason }) })).json();
  },
  async getProviderRefunds(orderId: number): Promise<MenuOrderRefund[]> {
    return readRefunds(await authRequest(`${privateBase}/${orderId}/refunds`));
  },
  async getCustomerRefunds(orderId: number): Promise<MenuOrderRefund[]> {
    return readRefunds(await authRequest(`${privateBase}/${orderId}/refunds/my`));
  },
  async getGuestRefunds(orderNumber: string, managementToken: string): Promise<MenuOrderRefund[]> {
    return readRefunds(await publicRequest(guestUrl(orderNumber, managementToken, "/refunds")));
  },
  async approveRefund(orderId: number, refundId: number, note?: string): Promise<MenuOrderRefund> {
    return (await authRequest(`${privateBase}/${orderId}/refunds/${refundId}/approve`, { method: "POST", body: JSON.stringify({ note: note?.trim() || "" }) })).json();
  },
  async rejectRefund(orderId: number, refundId: number, reason: string): Promise<MenuOrderRefund> {
    return (await authRequest(`${privateBase}/${orderId}/refunds/${refundId}/reject`, { method: "POST", body: JSON.stringify({ reason }) })).json();
  },
  async shippingQuote(
    supplierSlug: string,
    payload: MenuOrderShippingQuoteRequest,
    signal?: AbortSignal,
  ): Promise<MenuOrderShippingQuoteResponse> {
    const response = await publicRequest(
      `${publicBase}/shipping-quote/${encodeURIComponent(supplierSlug)}`,
      {
        method: "POST",
        headers: {
          Accept: "application/json",
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
        signal,
      },
    );

    return response.json();
  },

  async publicSettings(
    supplierSlug: string,
    menuId: number,
    signal?: AbortSignal,
  ): Promise<MenuOrderSettings> {
    const url =
      `${publicBase}/settings/` +
      `${encodeURIComponent(supplierSlug)}/${menuId}`;

    const response = await fetch(url, {
      cache: "no-store",
      signal,
    });

    if (response.status === 404) {
      return defaultPublicSettings(menuId);
    }

    if (!response.ok) await throwForResponse(response);
    return normalizeSettings(await response.json(), menuId);
  },

  async createPublic(
    supplierSlug: string,
    payload: MenuOrderCreatePayload,
  ): Promise<MenuOrderCreated> {
    if (
      payload.items.some(
        (item) =>
          !Number.isInteger(item.quantity) ||
          item.quantity < 1 ||
          (item.variant_id != null &&
            (!Number.isInteger(item.variant_id) || item.variant_id < 1)),
      )
    ) {
      throw new Error("Revisa la cantidad y presentación de cada producto.");
    }

    // fetchWithAuth funciona también sin token y, cuando existe una sesión,
    // permite que el backend relacione el pedido con el usuario actual.
    const response = await authRequest(
      `${publicBase}/${encodeURIComponent(supplierSlug)}`,
      {
        method: "POST",
        body: JSON.stringify(payload),
      },
    );

    return response.json();
  },

  async authorizeCard(
    orderNumber: string,
    managementToken: string,
    card: { card_token: string; payment_method_id: string; issuer_id: string | null },
  ): Promise<MenuOrder> {
    const params = new URLSearchParams({ management_token: managementToken });
    const response = await publicRequest(
      `${publicBase}/${encodeURIComponent(orderNumber)}/card/authorize?${params.toString()}`,
      {
        method: "POST",
        headers: { Accept: "application/json", "Content-Type": "application/json" },
        body: JSON.stringify(card),
      },
    );
    return response.json();
  },

  async confirmDelivery(orderId: number, code: string): Promise<MenuOrder> {
    const response = await authRequest(`${privateBase}/${orderId}/confirm-delivery`, {
      method: "POST",
      body: JSON.stringify({ code }),
    });
    return response.json();
  },

  async publicOrder(
    orderNumber: string,
    managementToken: string,
    signal?: AbortSignal,
  ): Promise<MenuOrder> {
    const params = new URLSearchParams({
      management_token: managementToken,
    });

    const response = await publicRequest(
      `${publicBase}/${encodeURIComponent(orderNumber)}?${params.toString()}`,
      { signal },
    );

    return response.json();
  },

  async settings(
    menuId: number,
    signal?: AbortSignal,
  ): Promise<MenuOrderSettings> {
    const response = await authRequest(
      `${privateBase}/settings/${menuId}`,
      { signal },
    );

    return normalizeSettings(await response.json(), menuId);
  },

  async updateSettings(
    menuId: number,
    payload: MenuOrderSettingsUpdate,
  ): Promise<MenuOrderSettings> {
    const response = await authRequest(
      `${privateBase}/settings/${menuId}`,
      {
        method: "PUT",
        body: JSON.stringify(payload),
      },
    );

    return normalizeSettings(await response.json(), menuId);
  },

  async mine(
    status?: MenuOrderStatus | null,
    signal?: AbortSignal,
  ): Promise<MenuOrder[]> {
    const response = await authRequest(
      `${privateBase}/mine${buildStatusQuery(status)}`,
      { signal },
    );

    const data: unknown = await response.json();
    return Array.isArray(data) ? (data as MenuOrder[]) : [];
  },

  async providerOrders(
    status?: MenuOrderStatus | null,
    signal?: AbortSignal,
  ): Promise<MenuOrder[]> {
    const response = await authRequest(
      `${privateBase}${buildStatusQuery(status)}`,
      { signal },
    );

    const data: unknown = await response.json();
    return Array.isArray(data) ? (data as MenuOrder[]) : [];
  },

  async providerOrder(
    orderId: number,
    signal?: AbortSignal,
  ): Promise<MenuOrder> {
    const response = await authRequest(
      `${privateBase}/${orderId}`,
      { signal },
    );
    return response.json();
  },

  async updateStatus(
    orderId: number,
    payload: MenuOrderStatusUpdate,
  ): Promise<MenuOrder> {
    const response = await authRequest(
      `${privateBase}/${orderId}/status`,
      {
        method: "PATCH",
        body: JSON.stringify(payload),
      },
    );
    return response.json();
  },
};
